# Mask audit (deterministic, pre-verdict): alignment of
# the mask inside its final box + straight-cut-edge
# detection. These catch "subject missing / mask
# shifted in frame" defects that fill/coverage alone
# score as healthy (field failures 2026-09-29).
audit = {}
try:
    _m = (np.asarray(alpha_img)[..., 3] > 127)
    _ys, _xs = np.nonzero(_m)
    if len(_xs) and len(_ys):
        _h, _w = _m.shape
        inset = {
            "left": _xs.min() / _w,
            "right": (_w - 1 - _xs.max()) / _w,
            "top": _ys.min() / _h,
            "bottom": (_h - 1 - _ys.max()) / _h,
        }
        worst_inset = max(inset.values())
        if worst_inset > 0.10:
            audit["mask_inset"] = {
                k: round(v, 3)
                for k, v in inset.items()}
        cx, cy = _xs.mean() / _w, _ys.mean() / _h
        off = max(abs(cx - 0.5) * 2, abs(cy - 0.5) * 2)
        audit["centroid_offset"] = round(off, 3)
        edges = {
            "top": _m[0, :].mean(),
            "bottom": _m[-1, :].mean(),
            "left": _m[:, 0].mean(),
            "right": _m[:, -1].mean(),
        }
        cuts = [k for k, v in edges.items()
                if v > 0.85]
        if cuts:
            audit["straight_cut_edges"] = cuts
    p["_mask_audit"] = audit
except Exception as exc:  # noqa: BLE001
    p["_mask_audit"] = {"error": str(exc)}

