#!/usr/bin/env python3
"""plan-io — PLAN.md 表格读写/统计（管线状态回填与汇总，确定性）。

用法：
  python plan-io.py stats <PLAN.md>                    # 进度统计
  python plan-io.py set <PLAN.md> <页id> <状态> [偏差]  # 回填单页状态
  python plan-io.py pending <PLAN.md>                  # 列出未完成页
状态机：pending / in_progress / done / failed / 降级后置
"""
from __future__ import annotations

import re
import sys

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

VALID = {"pending", "in_progress", "done", "failed", "降级后置"}


def _rows(text: str):
    for line in text.splitlines():
        if line.startswith("| p") and "---" not in line:
            cells = [c.strip() for c in line.strip("|").split("|")]
            if len(cells) >= 6:
                yield cells


def main() -> int:
    if len(sys.argv) < 3:
        print(__doc__); return 1
    op, path = sys.argv[1], sys.argv[2]
    text = open(path, encoding="utf-8").read()

    if op == "stats":
        rows = list(_rows(text))
        by = {}
        for c in rows:
            by[c[4]] = by.get(c[4], 0) + 1
        print("total:", len(rows), "|", by)
        return 0
    if op == "pending":
        for c in _rows(text):
            if c[4] in ("pending", "in_progress", "failed"):
                print(c[0], c[4])
        return 0
    if op == "set":
        if len(sys.argv) < 5:
            print("set needs: <PLAN.md> <页id> <状态> [偏差]"); return 1
        pid, status = sys.argv[3], sys.argv[4]
        dev = sys.argv[5] if len(sys.argv) > 5 else ""
        if status not in VALID:
            print(f"invalid status: {status} (valid: {VALID})"); return 1
        lines = text.splitlines()
        hit = False
        for i, line in enumerate(lines):
            if line.startswith(f"| {pid} "):
                cells = [c.strip() for c in line.strip("|").split("|")]
                while len(cells) < 7: cells.append("")
                cells[4], cells[6] = status, dev
                lines[i] = "| " + " | ".join(cells) + " |"
                hit = True
                break
        if not hit:
            print(f"row not found: {pid}"); return 1
        open(path, "w", encoding="utf-8", newline="").write(
            "\n".join(lines) + "\n")
        print(f"set {pid} -> {status}")
        return 0
    print("unknown op"); return 1


if __name__ == "__main__":
    sys.exit(main())

