                    brief = (inp.get("command") or inp.get("description") or "")[:160]
                elif name in ("Write", "Edit", "Read"):
                    brief = (inp.get("file_path") or "")[:120]
                elif name in ("Agent", "Task"):
                    brief = (inp.get("description") or "")[:100]
                elif name == "WebSearch":
